# 풀에서 열 번 빌리고 돌려주면
for (int i = 0; i < 10; i++) {
    Connection con = dataSource.getConnection();
    log.info("connection={}", con);
    con.close();
}

#   connection=HikariProxyConnection@1000 wrapping conn0: url=jdbc:h2:...
#   connection=HikariProxyConnection@1001 wrapping conn0: url=jdbc:h2:...
#   connection=HikariProxyConnection@1002 wrapping conn0: url=jdbc:h2:...

# 프록시는 매번 새것인데 wrapping conn0 은 같다

# H2 세션 수
select count(*) from information_schema.sessions;
#   2   (콘솔 + 풀의 커넥션 하나)

# 2 장에서는 열 개였다

# close 를 빼면
for (int i = 0; i < 20; i++) {
    dataSource.getConnection();   // 반납하지 않는다
}

#   conn0 ... conn9 까지 빌려 간 뒤
# java.sql.SQLTransientConnectionException:
#   HikariPool-1 - Connection is not available, request timed out after 30000ms.

# 30 초 기다리다 실패한다
